import com.salutem.order.RemoteSubreportMatcher;import java.util.*;
public class RemoteSubreportMatcherTest {
 public static void main(String[]args){var a=new RemoteSubreportMatcher.Resource("percentual_cirurgias","jrxml","/unit_files/percentual_cirurgias",new Object());var compiled=new RemoteSubreportMatcher.Resource("percentual_cirurgias","jasper","/compiled",null);if(RemoteSubreportMatcher.choose("\"percentual_cirurgias.jasper\"",List.of(a,compiled))!=a)throw new AssertionError("Não escolheu fonte JRXML");if(RemoteSubreportMatcher.choose("$P{SUBREPORT}",List.of(a))!=null)throw new AssertionError("Expressão dinâmica interceptada");if(RemoteSubreportMatcher.choose("\"outro.jasper\"",List.of(a))!=null)throw new AssertionError("Fonte incorreto");var b=new RemoteSubreportMatcher.Resource("percentual_cirurgias.jrxml","jrxml","/other",null);try{RemoteSubreportMatcher.choose("\"percentual_cirurgias.jasper\"",List.of(a,b));throw new AssertionError("Ambiguidade ignorada");}catch(IllegalStateException expected){}if(RemoteSubreportMatcher.choose("\"percentual_cirurgias.jasper\"",List.of(a,a))!=a)throw new AssertionError("Mesmo recurso duplicado");System.out.println("PASS: fonte remoto por nome, compilado excluído, expressão dinâmica e ambiguidade.");}
}
